import type { VerticalTabBarHeaderProps } from "../vertical-tab-bar.types";

import { forwardRef } from "react";
import { clsx } from "clsx";

import { VerticalTabBarClasses } from "../vertical-tab-bar.styles";

export const VerticalTabBarHeader = forwardRef<HTMLDivElement, VerticalTabBarHeaderProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(VerticalTabBarClasses.header, className)} {...props}>
        {children}
      </div>
    );
  },
);

VerticalTabBarHeader.displayName = "VerticalTabBar.Header";
